import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { Save, ArrowLeft, RotateCcw, AlertCircle } from 'lucide-react'
import {
  getGlobalAgent,
  updateGlobalAgent,
  getProjectAgent,
  updateProjectAgent,
} from '../lib/api'
import { toast } from '../components/Toast'
import AgentIcon from '../components/AgentIcon'

interface Props {
  scope: 'global' | 'project'
}

export default function AgentEditor({ scope }: Props) {
  const { name, projectId } = useParams()
  const navigate = useNavigate()
  const [content, setContent] = useState('')
  const [originalContent, setOriginalContent] = useState('')
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState('')
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      setLoadError('')
      try {
        const agent =
          scope === 'global'
            ? await getGlobalAgent(name!)
            : await getProjectAgent(projectId!, name!)
        setContent(agent.raw)
        setOriginalContent(agent.raw)
      } catch (err) {
        setLoadError(err instanceof Error ? err.message : 'Failed to load agent')
      }
      setLoading(false)
    }
    load()
  }, [name, projectId, scope])

  const handleSave = async () => {
    if (!content.trim()) {
      toast('error', 'Agent content cannot be empty')
      return
    }
    setSaving(true)
    try {
      if (scope === 'global') {
        await updateGlobalAgent(name!, content)
      } else {
        await updateProjectAgent(projectId!, name!, content)
      }
      setOriginalContent(content)
      setDirty(false)
      toast('success', 'Agent saved')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to save agent')
    } finally {
      setSaving(false)
    }
  }

  const backPath = scope === 'global' ? '/agents' : `/projects/${projectId}`

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (loadError) {
    return (
      <div className="p-8 flex flex-col items-center justify-center h-64 gap-3">
        <AlertCircle className="w-8 h-8 text-red" />
        <p className="text-red font-medium">{loadError}</p>
        <button onClick={() => navigate(backPath)} className="text-sm text-accent hover:underline">
          Go back
        </button>
      </div>
    )
  }

  return (
    <div className="p-8 max-w-5xl h-screen flex flex-col">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-4">
          <button
            onClick={() => {
              if (dirty && !confirm('You have unsaved changes. Leave anyway?')) return
              navigate(backPath)
            }}
            className="p-2 rounded-lg text-text-muted hover:text-text hover:bg-surface-2 transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
              <AgentIcon name={name!} uid={`editor-${name}`} size={40} global={scope === 'global'} />
              {name}
            </h1>
            <p className="text-text-secondary text-sm mt-0.5">
              {scope === 'global' ? 'Global agent' : 'Project agent'} — Edit raw markdown
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {dirty && (
            <button
              onClick={() => {
                setContent(originalContent)
                setDirty(false)
              }}
              className="flex items-center gap-2 px-3 py-2 text-sm text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
            >
              <RotateCcw className="w-4 h-4" />
              Reset
            </button>
          )}
          <button
            onClick={handleSave}
            disabled={!dirty || saving}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            <Save className="w-4 h-4" />
            {saving ? 'Saving...' : 'Save'}
          </button>
        </div>
      </div>

      <div className="flex-1 min-h-0">
        <textarea
          value={content}
          onChange={(e) => {
            setContent(e.target.value)
            setDirty(true)
          }}
          className="w-full h-full bg-surface border border-border rounded-xl p-5 font-mono text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors"
          placeholder="---&#10;name: Agent Name&#10;description: What this agent does&#10;model: sonnet&#10;---&#10;&#10;Agent instructions..."
          spellCheck={false}
        />
      </div>
    </div>
  )
}

import { useState, memo } from 'react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter'
import { oneDark } from 'react-syntax-highlighter/dist/esm/styles/prism'
import { Copy, Check, Terminal } from 'lucide-react'

function CopyButton({ text, size = 'sm' }: { text: string; size?: 'sm' | 'md' }) {
  const [copied, setCopied] = useState(false)
  const handleCopy = () => {
    navigator.clipboard.writeText(text)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }
  return (
    <button
      onClick={handleCopy}
      className={`flex items-center gap-1 transition-colors ${
        size === 'sm'
          ? 'text-[10px] text-zinc-400 hover:text-zinc-200'
          : 'text-[11px] text-text-muted hover:text-text'
      }`}
      title="Copy code"
    >
      {copied ? (
        <><Check className="w-3 h-3 text-green" /> Copied</>
      ) : (
        <><Copy className="w-3 h-3" /> Copy</>
      )}
    </button>
  )
}

export const MarkdownRenderer = memo(function MarkdownRenderer({ content }: { content: string }) {
  return (
    <div className="markdown-chat">
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        components={{
          code({ className, children, ...props }) {
            const match = /language-(\w+)/.exec(className || '')
            const codeString = String(children).replace(/\n$/, '')
            const isInline = !match && !codeString.includes('\n')
            void props // suppress unused

            if (isInline) {
              return (
                <code className="font-mono text-[0.88em] text-accent bg-accent/8 px-1.5 py-0.5 rounded-md border border-accent/15">
                  {children}
                </code>
              )
            }

            const language = match ? match[1] : 'text'

            return (
              <div className="my-3 rounded-lg border border-border overflow-hidden">
                <div className="flex items-center justify-between px-3 py-1.5 bg-surface-2 border-b border-border">
                  <div className="flex items-center gap-1.5">
                    <Terminal className="w-3 h-3 text-text-muted" />
                    <span className="text-[10px] font-mono text-text-muted tracking-wider">{language}</span>
                  </div>
                  <CopyButton text={codeString} />
                </div>
                <SyntaxHighlighter
                  style={oneDark}
                  language={language}
                  PreTag="div"
                  customStyle={{
                    margin: 0,
                    borderRadius: '0 0 0.5rem 0.5rem',
                    fontSize: '12px',
                    lineHeight: '1.65',
                    background: '#1e1e2e',
                  }}
                  codeTagProps={{ style: { fontFamily: 'var(--font-mono)' } }}
                >
                  {codeString}
                </SyntaxHighlighter>
              </div>
            )
          },
          pre: ({ children }) => <>{children}</>,
          h1: ({ children }) => <h3 className="text-[15px] font-bold text-text mt-4 mb-1.5">{children}</h3>,
          h2: ({ children }) => <h4 className="text-[14px] font-semibold text-text mt-3.5 mb-1.5">{children}</h4>,
          h3: ({ children }) => <h5 className="text-[13px] font-semibold text-text mt-3 mb-1">{children}</h5>,
          h4: ({ children }) => <h6 className="text-[13px] font-medium text-text-secondary mt-2.5 mb-1">{children}</h6>,
          p: ({ children }) => <p className="my-1.5 text-[13px] text-text-secondary leading-relaxed">{children}</p>,
          ul: ({ children }) => <ul className="my-2 space-y-1 list-none">{children}</ul>,
          ol: ({ children, start }) => <ol className="my-2 space-y-1.5 list-none" start={start}>{children}</ol>,
          li: ({ children, ...props }) => {
            const ordered = (props as Record<string, unknown>).ordered
            const index = (props as Record<string, unknown>).index as number | undefined
            return (
              <li className="flex items-start gap-2 text-[13px] text-text-secondary leading-relaxed">
                {ordered ? (
                  <span className="mt-[1px] w-5 h-5 rounded-md bg-surface-2 text-text-muted text-[10px] font-bold flex items-center justify-center shrink-0 border border-border">
                    {(index ?? 0) + 1}
                  </span>
                ) : (
                  <span className="mt-[7px] w-1 h-1 rounded-full bg-text-muted shrink-0" />
                )}
                <span className="flex-1">{children}</span>
              </li>
            )
          },
          a: ({ href, children }) => (
            <a
              href={href}
              target={href?.startsWith('http') ? '_blank' : undefined}
              rel={href?.startsWith('http') ? 'noopener noreferrer' : undefined}
              className="text-accent hover:text-accent-hover font-medium underline decoration-accent/30 underline-offset-2 hover:decoration-accent/60 transition-colors"
            >
              {children}
            </a>
          ),
          strong: ({ children }) => <strong className="font-semibold text-text">{children}</strong>,
          em: ({ children }) => <em className="italic text-text-secondary">{children}</em>,
          blockquote: ({ children }) => (
            <blockquote className="border-l-2 border-accent/40 pl-3 my-2 text-text-secondary italic">
              {children}
            </blockquote>
          ),
          hr: () => <hr className="my-3 border-border" />,
          table: ({ children }) => (
            <div className="my-3 rounded-lg border border-border overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-[12px]">{children}</table>
              </div>
            </div>
          ),
          thead: ({ children }) => <thead className="bg-surface-2">{children}</thead>,
          th: ({ children }) => (
            <th className="px-3 py-2 text-left text-[11px] font-semibold text-text border-b border-border">{children}</th>
          ),
          td: ({ children }) => (
            <td className="px-3 py-2 text-[12px] text-text-secondary border-b border-border/50">{children}</td>
          ),
          tr: ({ children }) => <tr className="border-b border-border last:border-0">{children}</tr>,
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  )
})

import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import {
  Bot,
  Plus,
  Trash2,
  Clock,
  Globe,
  FolderOpen,
  Search,
  Copy,
  ArrowRightLeft,
  X,
} from 'lucide-react'
import {
  getUnifiedAgents,
  deleteGlobalAgent,
  deleteProjectAgent,
  copyAgent,
  moveAgent,
  updateGlobalAgent,
  updateProjectAgent,
  sanitizeName,
} from '../lib/api'
import { useApi } from '../hooks/useApi'
import type { UnifiedAgent } from '../types'
import { getProjects } from '../lib/api'
import { toast } from '../components/Toast'
import AgentIcon from '../components/AgentIcon'

export default function AllAgents() {
  const { data: agents, loading, refetch } = useApi(getUnifiedAgents)
  const { data: projects } = useApi(getProjects)
  const navigate = useNavigate()

  const [search, setSearch] = useState('')
  const [scopeFilter, setScopeFilter] = useState<'all' | 'global' | 'project'>('all')
  const [projectFilter, setProjectFilter] = useState<string>('all')
  const [actionAgent, setActionAgent] = useState<UnifiedAgent | null>(null)
  const [actionType, setActionType] = useState<'copy' | 'move' | null>(null)
  const [actionTarget, setActionTarget] = useState<string>('')
  const [creating, setCreating] = useState(false)
  const [createLoading, setCreateLoading] = useState(false)
  const [newName, setNewName] = useState('')
  const [createScope, setCreateScope] = useState<string>('global')
  const [deletingKeys, setDeletingKeys] = useState<Set<string>>(new Set())
  const [actioning, setActioning] = useState(false)

  const filtered = (agents || []).filter((a) => {
    if (search && !a.name.toLowerCase().includes(search.toLowerCase()) && !a.description.toLowerCase().includes(search.toLowerCase())) return false
    if (scopeFilter === 'global' && a.scope !== 'global') return false
    if (scopeFilter === 'project' && a.scope !== 'project') return false
    if (projectFilter !== 'all' && a.scope === 'project' && a.projectId !== projectFilter) return false
    if (projectFilter !== 'all' && a.scope === 'global' && projectFilter !== 'global') return false
    return true
  })

  // Group by scope
  const globalAgents = filtered.filter((a) => a.scope === 'global')
  const projectGroups = new Map<string, UnifiedAgent[]>()
  for (const a of filtered.filter((a) => a.scope === 'project')) {
    const key = a.projectName || 'Unknown'
    if (!projectGroups.has(key)) projectGroups.set(key, [])
    projectGroups.get(key)!.push(a)
  }

  const handleDelete = async (agent: UnifiedAgent) => {
    if (!confirm(`Delete agent "${agent.name}" from ${agent.scopeLabel}?`)) return
    const key = agent.scope === 'global' ? `global-${agent.filename}` : `${agent.projectId}-${agent.filename}`
    setDeletingKeys((prev) => new Set(prev).add(key))
    try {
      if (agent.scope === 'global') {
        await deleteGlobalAgent(agent.filename)
      } else {
        await deleteProjectAgent(agent.projectId!, agent.filename)
      }
      refetch()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to delete agent')
    } finally {
      setDeletingKeys((prev) => { const s = new Set(prev); s.delete(key); return s })
    }
  }

  const handleAction = async () => {
    if (!actionAgent || !actionType || !actionTarget) return
    setActioning(true)
    try {
      const from = actionAgent.scope === 'global' ? 'global' : actionAgent.projectId!
      const to = actionTarget
      if (actionType === 'copy') {
        await copyAgent(from, to, actionAgent.filename)
        toast('success', `Agent copied`)
      } else {
        await moveAgent(from, to, actionAgent.filename)
        toast('success', `Agent moved`)
      }
      setActionAgent(null)
      setActionType(null)
      setActionTarget('')
      refetch()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : `Failed to ${actionType} agent`)
    } finally {
      setActioning(false)
    }
  }

  const handleCreate = async () => {
    if (!newName.trim()) return
    const slug = sanitizeName(newName)
    if (!slug) {
      toast('error', 'Invalid name — use letters, numbers, or hyphens')
      return
    }
    setCreateLoading(true)
    try {
      const template = `---\nname: ${newName.trim()}\ndescription: ""\nmodel: ""\n---\n\n# ${newName.trim()}\n\nWrite your agent instructions here.\n`
      if (createScope === 'global') {
        await updateGlobalAgent(slug, template)
        navigate(`/global/agents/${slug}`)
      } else {
        await updateProjectAgent(createScope, slug, template)
        navigate(`/projects/${createScope}/agents/${slug}`)
      }
      setCreating(false)
      setNewName('')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to create agent')
    } finally {
      setCreateLoading(false)
    }
  }

  const projectList = projects || []
  const uniqueProjects = [...new Map(projectList.map((p) => [p.id, p])).values()]

  if (loading) return <PageLoader />

  return (
    <div className="p-8 max-w-6xl">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <Bot className="w-6 h-6 text-purple" />
            All Agents
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            {agents?.length || 0} agents across {projectGroups.size} projects + global
          </p>
        </div>
        <button
          onClick={() => setCreating(true)}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
        >
          <Plus className="w-4 h-4" />
          New Agent
        </button>
      </div>

      {/* Filters bar */}
      <div className="flex items-center gap-3 mb-6">
        <div className="relative flex-1 max-w-sm">
          <Search className="w-4 h-4 text-text-muted absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search agents..."
            className="w-full bg-surface border border-border rounded-lg pl-9 pr-3 py-2 text-sm focus:outline-none focus:border-accent/50"
          />
        </div>

        <div className="flex items-center gap-1 bg-surface border border-border rounded-lg p-0.5">
          {(['all', 'global', 'project'] as const).map((s) => (
            <button
              key={s}
              onClick={() => setScopeFilter(s)}
              className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                scopeFilter === s
                  ? 'bg-accent text-white'
                  : 'text-text-secondary hover:text-text'
              }`}
            >
              {s === 'all' ? 'All' : s === 'global' ? 'Global' : 'Projects'}
            </button>
          ))}
        </div>

        {uniqueProjects.length > 0 && (
          <select
            value={projectFilter}
            onChange={(e) => setProjectFilter(e.target.value)}
            className="bg-surface border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50 appearance-none cursor-pointer"
          >
            <option value="all">All sources</option>
            <option value="global">Global only</option>
            {uniqueProjects.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
        )}
      </div>

      {/* Create modal */}
      {creating && (
        <div className="mb-6 bg-surface border border-accent/30 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <p className="text-sm font-semibold">Create New Agent</p>
            <button onClick={() => { setCreating(false); setNewName('') }} className="text-text-muted hover:text-text">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="flex gap-3">
            <input
              type="text"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder="Agent name..."
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && handleCreate()}
            />
            <select
              value={createScope}
              onChange={(e) => setCreateScope(e.target.value)}
              className="bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50"
            >
              <option value="global">Global</option>
              {uniqueProjects.map((p) => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
            <button
              onClick={handleCreate}
              disabled={createLoading}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              {createLoading ? 'Creating...' : 'Create'}
            </button>
          </div>
        </div>
      )}

      {/* Copy/Move modal */}
      {actionAgent && actionType && (
        <div className="mb-6 bg-surface border border-accent/30 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <p className="text-sm font-semibold">
              {actionType === 'copy' ? 'Copy' : 'Move'} "{actionAgent.name}" from {actionAgent.scopeLabel}
            </p>
            <button onClick={() => { setActionAgent(null); setActionType(null) }} className="text-text-muted hover:text-text">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="flex gap-3">
            <select
              value={actionTarget}
              onChange={(e) => setActionTarget(e.target.value)}
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
            >
              <option value="">Select destination...</option>
              {actionAgent.scope !== 'global' && <option value="global">Global</option>}
              {uniqueProjects
                .filter((p) => p.id !== actionAgent.projectId)
                .map((p) => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
            </select>
            <button
              onClick={handleAction}
              disabled={!actionTarget || actioning}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              {actioning ? 'Working...' : actionType === 'copy' ? 'Copy' : 'Move'}
            </button>
          </div>
        </div>
      )}

      {/* Results */}
      {filtered.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <Bot className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">
            {search ? 'No agents match your search' : 'No agents found'}
          </p>
          <p className="text-text-muted text-sm mt-1">
            {search ? 'Try a different search term' : 'Create your first agent to get started'}
          </p>
        </div>
      ) : (
        <div className="space-y-8">
          {/* Global agents */}
          {globalAgents.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <Globe className="w-4 h-4 text-accent" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  Global
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {globalAgents.length}
                </span>
              </div>
              <div className="space-y-2">
                {globalAgents.map((agent) => (
                  <AgentRow
                    key={`global-${agent.filename}`}
                    agent={agent}
                    deleting={deletingKeys.has(`global-${agent.filename}`)}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          )}

          {/* Per-project groups */}
          {[...projectGroups.entries()].map(([projectName, projectAgents]) => (
            <div key={projectName}>
              <div className="flex items-center gap-2 mb-3">
                <FolderOpen className="w-4 h-4 text-amber" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  {projectName}
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {projectAgents.length}
                </span>
              </div>
              <div className="space-y-2">
                {projectAgents.map((agent) => (
                  <AgentRow
                    key={`${agent.projectId}-${agent.filename}`}
                    agent={agent}
                    deleting={deletingKeys.has(`${agent.projectId}-${agent.filename}`)}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}


function AgentRow({
  agent,
  deleting,
  onDelete,
  onCopy,
  onMove,
}: {
  agent: UnifiedAgent
  deleting: boolean
  onDelete: (a: UnifiedAgent) => void
  onCopy: (a: UnifiedAgent) => void
  onMove: (a: UnifiedAgent) => void
}) {
  const editLink =
    agent.scope === 'global'
      ? `/global/agents/${agent.filename}`
      : `/projects/${agent.projectId}/agents/${agent.filename}`

  return (
    <div className="group flex items-center justify-between bg-surface border border-border rounded-xl px-4 py-3 hover:border-accent/30 transition-all">
      <Link to={editLink} className="flex items-center gap-3.5 flex-1 min-w-0">
        <AgentIcon name={agent.name} uid={`${agent.scope}-${agent.filename}`} size={agent.scope === 'global' ? 48 : 40} global={agent.scope === 'global'} />
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="font-semibold text-sm group-hover:text-accent-hover transition-colors truncate">
              {agent.name}
            </h3>
            <span
              className={`text-[10px] px-1.5 py-0.5 rounded-md font-medium ${
                agent.scope === 'global'
                  ? 'bg-accent-muted text-accent-hover'
                  : 'bg-amber-muted text-amber'
              }`}
            >
              {agent.scopeLabel}
            </span>
          </div>
          {agent.description && (
            <p className="text-xs text-text-secondary mt-0.5 truncate">{agent.description}</p>
          )}
          <div className="flex items-center gap-3 mt-1.5">
            {agent.model && (
              <span className="text-[11px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded font-mono">
                {agent.model}
              </span>
            )}
            <span className="flex items-center gap-1 text-[11px] text-text-muted">
              <Clock className="w-3 h-3" />
              {new Date(agent.updatedAt).toLocaleDateString()}
            </span>
          </div>
        </div>
      </Link>

      {/* Actions */}
      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0 ml-3">
        <button
          onClick={(e) => { e.stopPropagation(); onCopy(agent) }}
          title="Copy to..."
          className="p-1.5 rounded-md text-text-muted hover:text-accent hover:bg-accent-muted transition-colors"
        >
          <Copy className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onMove(agent) }}
          title="Move to..."
          className="p-1.5 rounded-md text-text-muted hover:text-amber hover:bg-amber-muted transition-colors"
        >
          <ArrowRightLeft className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onDelete(agent) }}
          title="Delete"
          disabled={deleting}
          className="p-1.5 rounded-md text-text-muted hover:text-red hover:bg-red-muted disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          <Trash2 className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  )
}

function PageLoader() {
  return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

