  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.375rem 0.75rem;
  background: var(--color-surface-2);
  border-bottom: 1px solid var(--color-border);
}

input.new_string:
.markdown-chat .code-block-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.375rem 0.75rem;
  background: var(--color-surface-2);
  border-bottom: 1px solid var(--color-border);
}

/* ─── Rich Editor (Tiptap) ──────────────────────────────────────────────── */

.rich-editor-content {
  padding: 1.25rem 1.5rem;
  min-height: 300px;
  font-size: 14px;
  line-height: 1.75;
  color: var(--color-text);
}

.rich-editor-content > *:first-child {
  margin-top: 0;
}

/* Headings */
.rich-editor-content h1 {
  font-size: 1.5rem;
  font-weight: 700;
  margin: 1.5rem 0 0.5rem;
  color: var(--color-text);
}
.rich-editor-content h2 {
  font-size: 1.25rem;
  font-weight: 600;
  margin: 1.25rem 0 0.5rem;
  color: var(--color-text);
}
.rich-editor-content h3 {
  font-size: 1.1rem;
  font-weight: 600;
  margin: 1rem 0 0.4rem;
  color: var(--color-text);
}
.rich-editor-content h4 {
  font-size: 1rem;
  font-weight: 600;
  margin: 0.75rem 0 0.4rem;
  color: var(--color-text-secondary);
}

/* Paragraphs */
.rich-editor-content p {
  margin: 0.5rem 0;
}

/* Lists */
.rich-editor-content ul {
  list-style-type: disc;
  padding-left: 1.5rem;
  margin: 0.5rem 0;
}
.rich-editor-content ol {
  list-style-type: decimal;
  padding-left: 1.5rem;
  margin: 0.5rem 0;
}
.rich-editor-content li {
  margin: 0.2rem 0;
}
.rich-editor-content li p {
  margin: 0;
}

/* Task lists */
.rich-editor-content ul[data-type="taskList"] {
  list-style: none;
  padding-left: 0;
}
.rich-editor-content ul[data-type="taskList"] li {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
}
.rich-editor-content ul[data-type="taskList"] li label {
  margin-top: 0.15rem;
}
.rich-editor-content ul[data-type="taskList"] li input[type="checkbox"] {
  width: 1rem;
  height: 1rem;
  accent-color: var(--color-accent);
  border-radius: 3px;
  cursor: pointer;
  margin-top: 0.25rem;
}

/* Blockquote */
.rich-editor-content blockquote {
  border-left: 3px solid var(--color-accent);
  padding-left: 1rem;
  margin: 0.75rem 0;
  color: var(--color-text-secondary);
  font-style: italic;
}

/* Code inline */
.rich-editor-content code {
  font-family: var(--font-mono);
  font-size: 0.875em;
  background: var(--color-surface-2);
  color: var(--color-accent);
  padding: 0.15rem 0.4rem;
  border-radius: 0.375rem;
  border: 1px solid var(--color-border);
}

/* Code block */
.rich-editor-content pre {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: 0.75rem;
  padding: 1rem;
  margin: 0.75rem 0;
  overflow-x: auto;
}
.rich-editor-content pre code {
  background: none;
  border: none;
  padding: 0;
  color: var(--color-text);
  font-size: 13px;
  line-height: 1.6;
}

/* Horizontal rule */
.rich-editor-content hr {
  border: none;
  border-top: 1px solid var(--color-border);
  margin: 1.25rem 0;
}

/* Links */
.rich-editor-content a,
.editor-link {
  color: var(--color-accent);
  text-decoration: underline;
  text-decoration-color: var(--color-accent);
  text-underline-offset: 2px;
  cursor: pointer;
}

/* Images */
.rich-editor-content img,
.editor-image {
  max-width: 100%;
  height: auto;
  border-radius: 0.75rem;
  margin: 0.75rem 0;
  border: 1px solid var(--color-border);
}

/* Tables */
.rich-editor-content table {
  border-collapse: collapse;
  width: 100%;
  margin: 0.75rem 0;
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
  overflow: hidden;
}
.rich-editor-content th {
  background: var(--color-surface-2);
  font-weight: 600;
  font-size: 0.8125rem;
  text-align: left;
}
.rich-editor-content th,
.rich-editor-content td {
  border: 1px solid var(--color-border);
  padding: 0.5rem 0.75rem;
  min-width: 80px;
  vertical-align: top;
  font-size: 0.875rem;
}
.rich-editor-content td p,
.rich-editor-content th p {
  margin: 0;
}

/* Selected cell highlight */
.rich-editor-content .selectedCell {
  background: var(--color-accent-muted);
}

/* Mark / Highlight */
.rich-editor-content mark {
  background-color: rgba(245, 158, 11, 0.25);
  border-radius: 2px;
  padding: 0.05rem 0.15rem;
}

/* Strong */
.rich-editor-content strong {
  font-weight: 700;
  color: var(--color-text);
}

/* Strikethrough */
.rich-editor-content s {
  text-decoration: line-through;
  color: var(--color-text-muted);
}

/* Placeholder */
.rich-editor-content p.is-editor-empty:first-child::before {
  content: attr(data-placeholder);
  float: left;
  color: var(--color-text-muted);
  pointer-events: none;
  height: 0;
  opacity: 0.5;
}

