  margin: 0.75rem 0;
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
  overflow: hidden;
}
.rich-editor-content th {
  background: var(--color-surface-2);
  font-weight: 600;
  font-size: 0.8125rem;
