import { useEditor, EditorContent } from '@tiptap/react'
import StarterKit from '@tiptap/starter-kit'
import Image from '@tiptap/extension-image'
import { TableKit } from '@tiptap/extension-table'
import Link from '@tiptap/extension-link'
import Placeholder from '@tiptap/extension-placeholder'
import Underline from '@tiptap/extension-underline'
import Highlight from '@tiptap/extension-highlight'
import TaskList from '@tiptap/extension-task-list'
import TaskItem from '@tiptap/extension-task-item'
import { Markdown } from 'tiptap-markdown'
import { useCallback, useEffect, useRef } from 'react'
import {
  Bold, Italic, Underline as UnderlineIcon, Strikethrough, Code,
  Heading1, Heading2, Heading3,
  List, ListOrdered, CheckSquare,
  Quote, Minus, Link as LinkIcon, ImageIcon,
  Table as TableIcon, Highlighter,
  Undo2, Redo2,
  Plus, Trash2, ArrowUp, ArrowDown, ArrowLeft, ArrowRight,
} from 'lucide-react'

interface RichMarkdownEditorProps {
  content: string
  onChange: (markdown: string) => void
  placeholder?: string
  className?: string
}

export default function RichMarkdownEditor({ content, onChange, placeholder, className }: RichMarkdownEditorProps) {
  const isInternalUpdate = useRef(false)
  const lastContent = useRef(content)

  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: { levels: [1, 2, 3, 4] },
        codeBlock: { HTMLAttributes: { class: 'editor-code-block' } },
      }),
      Underline,
      Highlight.configure({ multicolor: false }),
      Link.configure({
        openOnClick: false,
        HTMLAttributes: { class: 'editor-link' },
      }),
      Image.configure({
        HTMLAttributes: { class: 'editor-image' },
      }),
      TableKit.configure({
        resizable: false,
      }),
      TaskList,
      TaskItem.configure({ nested: true }),
      Placeholder.configure({
        placeholder: placeholder || 'Start writing...',
      }),
      Markdown.configure({
        html: false,
        transformCopiedText: true,
        transformPastedText: true,
      }),
    ],
    content,
    editorProps: {
      attributes: {
        class: 'rich-editor-content focus:outline-none',
      },
    },
    onUpdate: ({ editor }) => {
      isInternalUpdate.current = true
      const md = editor.storage.markdown.getMarkdown()
      lastContent.current = md
      onChange(md)
    },
  })

  // Sync external content changes (e.g., initial load)
  useEffect(() => {
    if (!editor) return
    if (isInternalUpdate.current) {
      isInternalUpdate.current = false
      return
    }
    if (content !== lastContent.current) {
      lastContent.current = content
      editor.commands.setContent(content)
    }
  }, [content, editor])

  const addImage = useCallback(() => {
    if (!editor) return
    const url = window.prompt('Image URL:')
    if (url) {
      editor.chain().focus().setImage({ src: url }).run()
    }
  }, [editor])

  const addLink = useCallback(() => {
    if (!editor) return
    const previousUrl = editor.getAttributes('link').href
    const url = window.prompt('Link URL:', previousUrl)
    if (url === null) return
    if (url === '') {
      editor.chain().focus().extendMarkRange('link').unsetLink().run()
      return
    }
    editor.chain().focus().extendMarkRange('link').setLink({ href: url }).run()
  }, [editor])

  const addTable = useCallback(() => {
    if (!editor) return
    editor.chain().focus().insertTable({ rows: 3, cols: 3, withHeaderRow: true }).run()
  }, [editor])

  if (!editor) return null

  const ToolbarButton = ({ onClick, active, disabled, title, children }: {
    onClick: () => void; active?: boolean; disabled?: boolean; title: string; children: React.ReactNode
  }) => (
    <button
      onClick={onClick}
      disabled={disabled}
      title={title}
      className={`p-1.5 rounded-md transition-colors ${
        active
          ? 'bg-accent/15 text-accent'
          : 'text-text-muted hover:text-text hover:bg-surface-2'
      } ${disabled ? 'opacity-30 cursor-not-allowed' : ''}`}
    >
      {children}
    </button>
  )

  const Divider = () => <div className="w-px h-5 bg-border mx-0.5" />

  return (
    <div className={`flex flex-col border border-border rounded-xl overflow-hidden bg-surface ${className || ''}`}>
      {/* Toolbar */}
      <div className="flex items-center gap-0.5 px-2 py-1.5 border-b border-border bg-surface-2 flex-wrap">
        {/* Undo / Redo */}
        <ToolbarButton onClick={() => editor.chain().focus().undo().run()} disabled={!editor.can().undo()} title="Undo">
          <Undo2 className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().redo().run()} disabled={!editor.can().redo()} title="Redo">
          <Redo2 className="w-3.5 h-3.5" />
        </ToolbarButton>

        <Divider />

        {/* Text formatting */}
        <ToolbarButton onClick={() => editor.chain().focus().toggleBold().run()} active={editor.isActive('bold')} title="Bold (Ctrl+B)">
          <Bold className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().toggleItalic().run()} active={editor.isActive('italic')} title="Italic (Ctrl+I)">
          <Italic className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().toggleUnderline().run()} active={editor.isActive('underline')} title="Underline (Ctrl+U)">
          <UnderlineIcon className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().toggleStrike().run()} active={editor.isActive('strike')} title="Strikethrough">
          <Strikethrough className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().toggleCode().run()} active={editor.isActive('code')} title="Inline code">
          <Code className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().toggleHighlight().run()} active={editor.isActive('highlight')} title="Highlight">
          <Highlighter className="w-3.5 h-3.5" />
        </ToolbarButton>

        <Divider />

        {/* Headings */}
        <ToolbarButton onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()} active={editor.isActive('heading', { level: 1 })} title="Heading 1">
          <Heading1 className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()} active={editor.isActive('heading', { level: 2 })} title="Heading 2">
          <Heading2 className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().toggleHeading({ level: 3 }).run()} active={editor.isActive('heading', { level: 3 })} title="Heading 3">
          <Heading3 className="w-3.5 h-3.5" />
        </ToolbarButton>

        <Divider />

        {/* Lists */}
        <ToolbarButton onClick={() => editor.chain().focus().toggleBulletList().run()} active={editor.isActive('bulletList')} title="Bullet list">
          <List className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().toggleOrderedList().run()} active={editor.isActive('orderedList')} title="Numbered list">
          <ListOrdered className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().toggleTaskList().run()} active={editor.isActive('taskList')} title="Task list">
          <CheckSquare className="w-3.5 h-3.5" />
        </ToolbarButton>

        <Divider />

        {/* Blocks */}
        <ToolbarButton onClick={() => editor.chain().focus().toggleBlockquote().run()} active={editor.isActive('blockquote')} title="Blockquote">
          <Quote className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().toggleCodeBlock().run()} active={editor.isActive('codeBlock')} title="Code block">
          <Code className="w-4 h-4" />
        </ToolbarButton>
        <ToolbarButton onClick={() => editor.chain().focus().setHorizontalRule().run()} title="Horizontal rule">
          <Minus className="w-3.5 h-3.5" />
        </ToolbarButton>

        <Divider />

        {/* Insert */}
        <ToolbarButton onClick={addLink} active={editor.isActive('link')} title="Add link">
          <LinkIcon className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={addImage} title="Add image">
          <ImageIcon className="w-3.5 h-3.5" />
        </ToolbarButton>
        <ToolbarButton onClick={addTable} title="Insert table">
          <TableIcon className="w-3.5 h-3.5" />
        </ToolbarButton>

        {/* Table controls — show when cursor is in a table */}
        {editor.isActive('table') && (
          <>
            <Divider />
            <ToolbarButton onClick={() => editor.chain().focus().addColumnBefore().run()} title="Add column before">
              <ArrowLeft className="w-3 h-3" />
            </ToolbarButton>
            <ToolbarButton onClick={() => editor.chain().focus().addColumnAfter().run()} title="Add column after">
              <ArrowRight className="w-3 h-3" />
            </ToolbarButton>
            <ToolbarButton onClick={() => editor.chain().focus().addRowBefore().run()} title="Add row before">
              <ArrowUp className="w-3 h-3" />
            </ToolbarButton>
            <ToolbarButton onClick={() => editor.chain().focus().addRowAfter().run()} title="Add row after">
              <ArrowDown className="w-3 h-3" />
            </ToolbarButton>
            <ToolbarButton onClick={() => editor.chain().focus().deleteTable().run()} title="Delete table">
              <Trash2 className="w-3 h-3 text-red" />
            </ToolbarButton>
          </>
        )}
      </div>

      {/* Editor Content */}
      <EditorContent editor={editor} className="flex-1 overflow-y-auto" />
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import {
  Save, ArrowLeft, RotateCcw, AlertCircle, Code, Eye,
  Bot, Cpu, Wrench, FileText,
} from 'lucide-react'
import {
  getGlobalAgent,
  updateGlobalAgent,
  getProjectAgent,
  updateProjectAgent,
} from '../lib/api'
import { toast } from '../components/Toast'
import AgentIcon from '../components/AgentIcon'
import RichMarkdownEditor from '../components/RichMarkdownEditor'

interface Props {
  scope: 'global' | 'project'
}

// Parse frontmatter from raw markdown
function parseFrontmatter(raw: string): { meta: Record<string, string>; body: string } {
  const match = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/)
  if (!match) return { meta: {}, body: raw }
  const meta: Record<string, string> = {}
  for (const line of match[1].split('\n')) {
    const colonIdx = line.indexOf(':')
    if (colonIdx === -1) continue
    const key = line.slice(0, colonIdx).trim()
    let val = line.slice(colonIdx + 1).trim()
    // Strip surrounding quotes
    if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1)
    }
    if (key) meta[key] = val
  }
  return { meta, body: match[2].replace(/^\n+/, '') }
}

// Serialize frontmatter + body back to raw markdown
function serializeAgent(meta: Record<string, string>, body: string): string {
  const lines = Object.entries(meta)
    .filter(([, v]) => v !== undefined)
    .map(([k, v]) => {
      // Quote description if it contains special chars
      if (k === 'description' && v && (v.includes(':') || v.includes('#') || v.includes('"'))) {
        return `${k}: "${v.replace(/"/g, '\\"')}"`
      }
      return `${k}: ${v}`
    })
  return `---\n${lines.join('\n')}\n---\n\n${body}`
}

const MODEL_OPTIONS = ['', 'sonnet', 'opus', 'haiku']
const TOOL_OPTIONS = ['Read', 'Write', 'Edit', 'Bash', 'Glob', 'Grep', 'WebSearch', 'WebFetch']

export default function AgentEditor({ scope }: Props) {
  const { name, projectId } = useParams()
  const navigate = useNavigate()

  // Raw content
  const [originalContent, setOriginalContent] = useState('')
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState('')
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)

  // Parsed fields
  const [meta, setMeta] = useState<Record<string, string>>({})
  const [body, setBody] = useState('')

  // View mode: 'rich' or 'source'
  const [viewMode, setViewMode] = useState<'rich' | 'source'>('rich')

  // Source text for source mode
  const [sourceText, setSourceText] = useState('')

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      setLoadError('')
      try {
        const agent =
          scope === 'global'
            ? await getGlobalAgent(name!)
            : await getProjectAgent(projectId!, name!)
        setOriginalContent(agent.raw)
        const parsed = parseFrontmatter(agent.raw)
        setMeta(parsed.meta)
        setBody(parsed.body)
        setSourceText(agent.raw)
      } catch (err) {
        setLoadError(err instanceof Error ? err.message : 'Failed to load agent')
      }
      setLoading(false)
    }
    load()
  }, [name, projectId, scope])

  const getCurrentRaw = useCallback(() => {
    if (viewMode === 'source') return sourceText
    return serializeAgent(meta, body)
  }, [viewMode, sourceText, meta, body])

  const handleSave = async () => {
    const raw = getCurrentRaw()
    if (!raw.trim()) {
      toast('error', 'Agent content cannot be empty')
      return
    }
    setSaving(true)
    try {
      if (scope === 'global') {
        await updateGlobalAgent(name!, raw)
      } else {
        await updateProjectAgent(projectId!, name!, raw)
      }
      setOriginalContent(raw)
      setDirty(false)
      toast('success', 'Agent saved')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to save')
    } finally {
      setSaving(false)
    }
  }

  const handleReset = () => {
    const parsed = parseFrontmatter(originalContent)
    setMeta(parsed.meta)
    setBody(parsed.body)
    setSourceText(originalContent)
    setDirty(false)
  }

  const updateMeta = (key: string, value: string) => {
    setMeta(prev => ({ ...prev, [key]: value }))
    setDirty(true)
  }

  const handleBodyChange = useCallback((newBody: string) => {
    setBody(newBody)
    setDirty(true)
  }, [])

  const handleSourceChange = (text: string) => {
    setSourceText(text)
    setDirty(true)
  }

  // Sync between modes when switching
  const switchToSource = () => {
    setSourceText(serializeAgent(meta, body))
    setViewMode('source')
  }

  const switchToRich = () => {
    const parsed = parseFrontmatter(sourceText)
    setMeta(parsed.meta)
    setBody(parsed.body)
    setViewMode('rich')
  }

  const toggleTools = (tool: string) => {
    const current = (meta.tools || '').split(',').map(t => t.trim()).filter(Boolean)
    const updated = current.includes(tool)
      ? current.filter(t => t !== tool)
      : [...current, tool]
    updateMeta('tools', updated.join(','))
  }

  const selectedTools = (meta.tools || '').split(',').map(t => t.trim()).filter(Boolean)

  const backPath = scope === 'global' ? '/agents' : `/projects/${projectId}`

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (loadError) {
    return (
      <div className="p-8 flex flex-col items-center justify-center h-64 gap-3">
        <AlertCircle className="w-8 h-8 text-red" />
        <p className="text-red font-medium">{loadError}</p>
        <button onClick={() => navigate(backPath)} className="text-sm text-accent hover:underline">
          Go back
        </button>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-screen">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-border bg-surface shrink-0">
        <div className="flex items-center gap-4">
          <button
            onClick={() => {
              if (dirty && !confirm('You have unsaved changes. Leave anyway?')) return
              navigate(backPath)
            }}
            className="p-2 rounded-lg text-text-muted hover:text-text hover:bg-surface-2 transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <AgentIcon name={name!} uid={`editor-${name}`} size={40} global={scope === 'global'} />
          <div>
            <h1 className="text-lg font-bold">{meta.name || name}</h1>
            <p className="text-xs text-text-muted mt-0.5">
              {scope === 'global' ? 'Global agent' : 'Project agent'}
              {dirty && <span className="ml-2 text-amber font-medium">Unsaved changes</span>}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {/* Mode toggle */}
          <div className="flex items-center bg-surface-2 border border-border rounded-lg p-0.5 mr-2">
            <button
              onClick={viewMode === 'source' ? switchToRich : undefined}
              className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                viewMode === 'rich' ? 'bg-accent text-white' : 'text-text-muted hover:text-text'
              }`}
            >
              <Eye className="w-3.5 h-3.5" /> Rich Editor
            </button>
            <button
              onClick={viewMode === 'rich' ? switchToSource : undefined}
              className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                viewMode === 'source' ? 'bg-accent text-white' : 'text-text-muted hover:text-text'
              }`}
            >
              <Code className="w-3.5 h-3.5" /> Source
            </button>
          </div>

          {dirty && (
            <button onClick={handleReset} className="flex items-center gap-1.5 px-3 py-2 text-xs text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors">
              <RotateCcw className="w-3.5 h-3.5" /> Reset
            </button>
          )}
          <button
            onClick={handleSave}
            disabled={!dirty || saving}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-30 transition-colors"
          >
            <Save className="w-4 h-4" />
            {saving ? 'Saving...' : 'Save'}
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 flex min-h-0 overflow-hidden">
        {viewMode === 'rich' ? (
          <>
            {/* Frontmatter sidebar */}
            <div className="w-[300px] min-w-[300px] border-r border-border bg-surface overflow-y-auto">
              <div className="p-5 space-y-5">
                <div className="flex items-center gap-2 text-xs font-semibold text-text-muted uppercase tracking-wider">
                  <FileText className="w-3.5 h-3.5" />
                  Agent Config
                </div>

                {/* Name */}
                <div>
                  <label className="text-xs font-medium text-text-muted block mb-1.5">
                    <span className="flex items-center gap-1.5"><Bot className="w-3 h-3" /> Name</span>
                  </label>
                  <input
                    value={meta.name || ''}
                    onChange={e => updateMeta('name', e.target.value)}
                    className="w-full bg-surface-2 border border-border rounded-xl px-3.5 py-2.5 text-sm text-text focus:outline-none focus:border-accent/50 transition-colors"
                    placeholder="Agent Name"
                  />
                </div>

                {/* Description */}
                <div>
                  <label className="text-xs font-medium text-text-muted block mb-1.5">Description</label>
                  <textarea
                    value={meta.description || ''}
                    onChange={e => updateMeta('description', e.target.value)}
                    rows={3}
                    className="w-full bg-surface-2 border border-border rounded-xl px-3.5 py-2.5 text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors leading-relaxed"
                    placeholder="What does this agent do?"
                  />
                </div>

                {/* Model */}
                <div>
                  <label className="text-xs font-medium text-text-muted block mb-1.5">
                    <span className="flex items-center gap-1.5"><Cpu className="w-3 h-3" /> Model</span>
                  </label>
                  <select
                    value={meta.model || ''}
                    onChange={e => updateMeta('model', e.target.value)}
                    className="w-full bg-surface-2 border border-border rounded-xl px-3.5 py-2.5 text-sm text-text focus:outline-none focus:border-accent/50 transition-colors cursor-pointer"
                  >
                    {MODEL_OPTIONS.map(m => (
                      <option key={m} value={m}>{m || '(default)'}</option>
                    ))}
                  </select>
                </div>

                {/* Tools */}
                <div>
                  <label className="text-xs font-medium text-text-muted block mb-2">
                    <span className="flex items-center gap-1.5"><Wrench className="w-3 h-3" /> Tools</span>
                  </label>
                  <div className="flex flex-wrap gap-1.5">
                    {TOOL_OPTIONS.map(tool => (
                      <button
                        key={tool}
                        onClick={() => toggleTools(tool)}
                        className={`px-2.5 py-1.5 text-[11px] font-medium rounded-lg border transition-all ${
                          selectedTools.includes(tool)
                            ? 'bg-accent/10 border-accent/30 text-accent'
                            : 'bg-surface-2 border-border text-text-muted hover:text-text hover:border-border'
                        }`}
                      >
                        {tool}
                      </button>
                    ))}
                  </div>
                  {selectedTools.length > 0 && (
                    <p className="text-[10px] text-text-muted mt-2 font-mono">{selectedTools.join(', ')}</p>
                  )}
                </div>

                {/* Extra frontmatter fields */}
                {Object.entries(meta)
                  .filter(([k]) => !['name', 'description', 'model', 'tools'].includes(k))
                  .map(([key, val]) => (
                    <div key={key}>
                      <label className="text-xs font-medium text-text-muted block mb-1.5">{key}</label>
                      <input
                        value={val}
                        onChange={e => updateMeta(key, e.target.value)}
                        className="w-full bg-surface-2 border border-border rounded-xl px-3.5 py-2.5 text-sm text-text focus:outline-none focus:border-accent/50 transition-colors"
                      />
                    </div>
                  ))
                }
              </div>
            </div>

            {/* Rich editor body */}
            <div className="flex-1 min-w-0 overflow-y-auto bg-bg">
              <div className="max-w-4xl mx-auto py-2">
                <RichMarkdownEditor
                  content={body}
                  onChange={handleBodyChange}
                  placeholder="Write your agent instructions here..."
                  className="min-h-[calc(100vh-120px)] border-0 rounded-none bg-transparent"
                />
              </div>
            </div>
          </>
        ) : (
          /* Source mode - raw markdown textarea */
          <div className="flex-1 min-w-0 p-4">
            <textarea
              value={sourceText}
              onChange={e => handleSourceChange(e.target.value)}
              className="w-full h-full bg-surface border border-border rounded-xl p-5 font-mono text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors leading-relaxed"
              placeholder={'---\nname: Agent Name\ndescription: What this agent does\nmodel: sonnet\ntools: Read,Write,Edit\n---\n\nAgent instructions...'}
              spellCheck={false}
            />
          </div>
        )}
      </div>
    </div>
  )
}

