import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { Save, ArrowLeft, RotateCcw, Terminal, Info } from 'lucide-react'
import { getProjectCommand, updateProjectCommand } from '../lib/api'
import { toast } from '../components/Toast'

export default function CommandEditor() {
  const { projectId, name } = useParams()
  const navigate = useNavigate()
  const [content, setContent] = useState('')
  const [originalContent, setOriginalContent] = useState('')
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)
  const [isNew, setIsNew] = useState(false)

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      try {
        const cmd = await getProjectCommand(projectId!, name!)
        setContent(cmd.content)
        setOriginalContent(cmd.content)
      } catch {
        setContent('')
        setOriginalContent('')
        setIsNew(true)
      }
      setLoading(false)
    }
    load()
  }, [name, projectId])

  const handleSave = async () => {
    if (!content.trim()) {
      toast('error', 'Command content cannot be empty')
      return
    }
    setSaving(true)
    try {
      await updateProjectCommand(projectId!, name!, content)
      setOriginalContent(content)
      setDirty(false)
      setIsNew(false)
      toast('success', 'Command saved')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to save command')
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className="p-8 max-w-5xl h-screen flex flex-col">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-4">
          <button
            onClick={() => {
              if (dirty && !confirm('You have unsaved changes. Leave anyway?')) return
              navigate(`/projects/${projectId}`)
            }}
            className="p-2 rounded-lg text-text-muted hover:text-text hover:bg-surface-2 transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
              <Terminal className="w-6 h-6 text-amber" />
              /{name}
            </h1>
            <p className="text-text-secondary text-sm mt-0.5">
              {isNew ? 'New command' : 'Edit command'} — Slash command for Claude
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {dirty && (
            <button
              onClick={() => { setContent(originalContent); setDirty(false) }}
              className="flex items-center gap-2 px-3 py-2 text-sm text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
            >
              <RotateCcw className="w-4 h-4" />
              Reset
            </button>
          )}
          <button
            onClick={handleSave}
            disabled={!dirty || saving}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            <Save className="w-4 h-4" />
            {saving ? 'Saving...' : 'Save'}
          </button>
        </div>
      </div>

      <div className="bg-amber-muted border border-amber/20 rounded-xl p-4 mb-4 flex items-start gap-3">
        <Info className="w-4 h-4 text-amber shrink-0 mt-0.5" />
        <div className="text-xs text-text-secondary">
          <p className="font-medium text-amber mb-1">How slash commands work</p>
          <p>
            Type <code className="text-amber font-mono">/{name}</code> in Claude to run this command.
            Use <code className="text-amber font-mono">$ARGUMENTS</code> as a placeholder for user input.
          </p>
        </div>
      </div>

      <div className="flex-1 min-h-0">
        <textarea
          value={content}
          onChange={(e) => { setContent(e.target.value); setDirty(true) }}
          className="w-full h-full bg-surface border border-border rounded-xl p-5 font-mono text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors"
          placeholder={`# /${name}\n\nDescribe what this command does.\nUse $ARGUMENTS for user-provided input.`}
          spellCheck={false}
        />
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { Save, ArrowLeft, RotateCcw, ShieldCheck, Info } from 'lucide-react'
import { getProjectRule, updateProjectRule } from '../lib/api'
import { toast } from '../components/Toast'

export default function RuleEditor() {
  const { projectId, name } = useParams()
