  return (
    <div className="p-8 max-w-5xl h-screen flex flex-col">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-4">
          <button
            onClick={() => {
              if (dirty && !confirm('You have unsaved changes. Leave anyway?')) return
              navigate(`/projects/${projectId}`)
            }}
            className="p-2 rounded-lg text-text-muted hover:text-text hover:bg-surface-2 transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
              <ShieldCheck className="w-6 h-6 text-green" />
              {name}
            </h1>
            <p className="text-text-secondary text-sm mt-0.5">
              {isNew ? 'New rule' : 'Edit rule'} — Constraint Claude must follow
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {dirty && (
            <button
              onClick={() => { setContent(originalContent); setDirty(false) }}
              className="flex items-center gap-2 px-3 py-2 text-sm text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
            >
              <RotateCcw className="w-4 h-4" />
              Reset
            </button>
          )}
          <button
            onClick={handleSave}
            disabled={!dirty || saving}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            <Save className="w-4 h-4" />
            {saving ? 'Saving...' : 'Save'}
          </button>
        </div>
      </div>

      <div className="bg-green-muted border border-green/20 rounded-xl p-4 mb-4 flex items-start gap-3">
        <Info className="w-4 h-4 text-green shrink-0 mt-0.5" />
        <div className="text-xs text-text-secondary">
          <p className="font-medium text-green mb-1">How rules work</p>
          <p>Rules are constraints Claude always follows in this project. Be specific and actionable.</p>
        </div>
      </div>

      <div className="flex-1 min-h-0">
        <textarea
          value={content}
          onChange={(e) => { setContent(e.target.value); setDirty(true) }}
          className="w-full h-full bg-surface border border-border rounded-xl p-5 font-mono text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors"
          placeholder={`# ${name}\n\n- Always use the project's logger instead of console.log\n- Never hardcode credentials`}
          spellCheck={false}
        />
      </div>
    </div>
  )
